const {
  isSupportedThemeFile,
  getTemplateCandidates,
  extractJsonSectionFiles,
  extractLiquidReferences
} = require('../theme-utils');

function makeResult(overrides = {}) {
  return {
    status: 'success',
    created: 0,
    updated: 0,
    deleted: 0,
    warnings: [],
    errors: [],
    summary: {},
    ...overrides
  };
}

function addQueue(queue, seen, filename) {
  if (!filename || seen.has(filename)) {
    return;
  }

  seen.add(filename);
  queue.push(filename);
}

async function collectThemeDependencySeeds(config, client) {
  const filenames = new Set();

  if (config.objects.includes('pages')) {
    const pages = await client.source.pages.listAll();
    for (const page of pages) {
      for (const candidate of getTemplateCandidates('page', page.templateSuffix)) {
        filenames.add(candidate);
      }
    }
  }

  if (config.objects.includes('collections')) {
    const collections = await client.source.collections.listAll();
    for (const collection of collections) {
      for (const candidate of getTemplateCandidates('collection', collection.templateSuffix)) {
        filenames.add(candidate);
      }
    }
  }

  if (config.objects.includes('products')) {
    const products = await client.source.products.listAll();
    for (const product of products) {
      for (const candidate of getTemplateCandidates('product', product.templateSuffix)) {
        filenames.add(candidate);
      }
    }
  }

  return [...filenames];
}

async function resolveDependencyFiles(sourceThemeId, seedFilenames, sourceFilesByName, client, warnings) {
  const queue = [];
  const selected = new Set();

  for (const filename of seedFilenames) {
    if (sourceFilesByName.has(filename)) {
      addQueue(queue, selected, filename);
    } else if (filename) {
      warnings.push(`Theme dependency "${filename}" was not found in the source theme.`);
    }
  }

  while (queue.length > 0) {
    const filename = queue.shift();
    const file = sourceFilesByName.get(filename);
    if (!file) {
      continue;
    }

    const dependencies = new Set();
    for (const sectionFile of extractJsonSectionFiles(filename, file.content)) {
      dependencies.add(sectionFile);
    }

    const { snippets, assets } = extractLiquidReferences(file.content);
    for (const snippetFile of snippets) {
      dependencies.add(snippetFile);
    }
    for (const assetFile of assets) {
      dependencies.add(assetFile);
    }

    const unresolved = [];
    for (const dependency of dependencies) {
      if (sourceFilesByName.has(dependency)) {
        addQueue(queue, selected, dependency);
      } else {
        unresolved.push(dependency);
      }
    }

    if (unresolved.length > 0) {
      warnings.push(
        `Theme file "${filename}" references missing dependencies: ${unresolved.join(', ')}`
      );
    }
  }

  return client.source.themes.readFiles(sourceThemeId, [...selected]);
}

async function syncThemes({ config, client }) {
  const result = makeResult();

  try {
    const sourceThemeId = await client.source.themes.resolveThemeId();
    const destinationThemeId = await client.destination.themes.resolveThemeId(
      config.destinationThemeId
    );
    const sourceFiles = (await client.source.themes.listFiles(sourceThemeId)).filter(
      (file) => isSupportedThemeFile(file.filename)
    );
    const destinationFiles = (await client.destination.themes.listFiles(destinationThemeId)).filter(
      (file) => isSupportedThemeFile(file.filename)
    );
    const sourceFilesByName = new Map(sourceFiles.map((file) => [file.filename, file]));
    const destinationFilesByName = new Map(
      destinationFiles.map((file) => [file.filename, file])
    );

    let filesToSync;
    if (config.themeSyncMode === 'full') {
      filesToSync = await client.source.themes.readFiles(
        sourceThemeId,
        sourceFiles.map((file) => file.filename)
      );
    } else {
      const seeds = await collectThemeDependencySeeds(config, client);
      filesToSync = await resolveDependencyFiles(
        sourceThemeId,
        seeds,
        sourceFilesByName,
        client,
        result.warnings
      );
    }

    const selectedFiles = filesToSync.filter((file) => isSupportedThemeFile(file.filename));
    const upsertFiles = [];

    for (const file of selectedFiles) {
      const destinationFile = destinationFilesByName.get(file.filename);
      const unchanged =
        destinationFile &&
        destinationFile.content === file.content &&
        destinationFile.contentBase64 === file.contentBase64;

      if (!unchanged) {
        upsertFiles.push(file);
      }
    }

    if (upsertFiles.length > 0) {
      await client.destination.themes.upsertFiles(destinationThemeId, upsertFiles);

      for (const file of upsertFiles) {
        if (destinationFilesByName.has(file.filename)) {
          result.updated += 1;
        } else {
          result.created += 1;
        }
      }
    }

    if (config.cleanDestination && !config.createOnly && !config.updateOnly) {
      const deleteCandidates =
        config.themeSyncMode === 'full'
          ? destinationFiles
              .map((file) => file.filename)
              .filter((filename) => !sourceFilesByName.has(filename))
          : [];

      if (deleteCandidates.length > 0) {
        await client.destination.themes.deleteFiles(destinationThemeId, deleteCandidates);
        result.deleted += deleteCandidates.length;
      }
    }

    result.summary = {
      sourceThemeId,
      destinationThemeId,
      sourceCount: sourceFiles.length,
      destinationCount: destinationFiles.length,
      syncedCount: selectedFiles.length,
      themeSyncMode: config.themeSyncMode
    };
  } catch (error) {
    result.errors.push(error.message);
  }

  result.status = result.errors.length > 0 ? 'failed' : 'success';
  return result;
}

module.exports = {
  syncThemes
};
